V8,V16=_DATA
_route={}
_early={}
def agent(observation,configuration):
 p=int(observation.get("player",0));s=int(observation.get("step",0))
 if s==0:
  _route[p]=False;_early[p]=False
 market=observation.get("market") if isinstance(observation.get("market"),dict) else {}
 inv=market.get("inventory") if isinstance(market.get("inventory"),dict) else {}
 if s==72:
  _route[p]=float(inv.get("WHEAT",99999) or 99999)<=9972.5
 src=V16 if (_route.get(p,False) and s>=401) else V8
 i=min(s,len(src[p])-1);a=copy.deepcopy(src[p][i]);a["hands"]=a.get("hands",[])[:len(observation["farms"][p]["hands"])];return a
act=agent
